/** 仅接受 http/https 且 host 非空的地址；空串=禁用（契约语义），脏输入落回默认值。 */
private fun sanitizeBaseUrl(raw: String, fallback: String): String {
    val trimmed = raw.trim()
    if (trimmed.isEmpty()) return trimmed
    val uri = Uri.parse(trimmed)
    val valid = (uri.scheme == "http" || uri.scheme == "https") && !uri.host.isNullOrBlank()
    return if (valid) trimmed else fallback
}

